import { apiClient } from "@/shared/api/axion-instance";
import axios from "axios";


export type pagination = {
    search?: string,
    page: number
    pageSize: number
}

export const departamentsApi = {
    getDepartaments: async (request : pagination): Promise<Departament[]> => {
        const response = await apiClient.get<Departament[]>("/api/departaments/roots",{
            params: request
        });

        return response.data;
    }
}